	const normalized = value.trim().toLowerCase();
	if (!normalized.startsWith("zh") && !normalized.startsWith("en") && !normalized.startsWith("pt") && normalized !== "id" && !normalized.startsWith("id-") && !normalized.startsWith("id_") && normalized !== "in" && !normalized.startsWith("in-") && !normalized.startsWith("in_")) return;
